<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Model;
#[Fillable(['name','slug','document_title','description','paper_size','orientation','content','custom_css','html_template','css_template','placeholders','builder_data','is_active','created_by','updated_by'])]
class FoundationSkTemplate extends Model { protected function casts(): array { return ['placeholders'=>'array','builder_data'=>'array','is_active'=>'boolean']; } public function getBuilderDataAttribute($value): array { if (is_array($value)) return $value; if (is_string($value) && $value !== '') { $decoded=json_decode($value,true); if (is_array($decoded)) return $decoded; } return self::defaultBuilderData(); } public static function defaultBuilderData(): array { return ['header'=>['top_text'=>'','logo_path'=>'','institution_name'=>'','address'=>'','whatsapp'=>'','email'=>'','font_top_text'=>13,'font_institution_name'=>26,'font_address'=>11,'font_contact'=>11],'decision'=>['title'=>'','number'=>'','opening'=>'','font_title'=>13,'font_number'=>12,'font_opening'=>11],'sections'=>['menimbang'=>'','mengingat'=>'','memperhatikan'=>'','judul_tengah'=>'','memutuskan'=>'','menetapkan'=>''],'fonts'=>['body'=>11,'section_title'=>11,'judul_tengah'=>11,'data_user'=>11,'signature'=>11,'copies_title'=>11,'copies'=>11],'signature'=>['ditetapkan_di'=>'','label_tanggal'=>'','tanggal_penetapan'=>'','baris_pengurus'=>'','jabatan'=>'','nama'=>''],'copies'=>['title'=>'','items'=>'']]; } public function createdBy(){return $this->belongsTo(User::class,'created_by');} public function updatedBy(){return $this->belongsTo(User::class,'updated_by');} }
